#include <algorithm>
#include <functional>
#include <string>
#include <vector>

std::vector<std::pair<int,int>> free_slots(int limit, std::vector<std::pair<int,int>> busy) {
    std::sort(busy.begin(), busy.end());
    std::vector<std::pair<int,int>> result;
    int start = 0;
    int end = 0;

    while (start < busy.size()) {
        if (end == busy.size() || busy[end].first > limit) {
            result.push_back({start, end});
            start = end + 1;
        } else {
            end++;
        }
    }

    return result;
}

#include <algorithm>
#include <functional>
#include <string>
#include <vector>

int shortest_span(const std::vector<int>& values, long long threshold) {
    int n = values.size();
    std::vector<int> dp(n + 1, INT_MAX);
    dp[0] = 0;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < i; ++j) {
            if (values[j] < values[i]) {
                dp[i] = std::min(dp[i], dp[j] + values[i]);
            }
        }
    }

    return dp[n];
}

#include <algorithm>
#include <functional>
#include <string>
#include <vector>
#include <unordered_map>

std::vector<std::vector<int>> build_layers(int n, const std::vector<std::pair<int,int>>& prerequisites) {
    std::vector<std::vector<int>> layers;
    std::unordered_map<int, std::vector<int>> graph;
    std::unordered_map<int, int> indegree;

    // Build the graph
    for (const auto& pair : prerequisites) {
        int a = pair.first;
        int b = pair.second;
        graph[a].push_back(b);
        indegree[b]++;
    }

    // Topological sort
    std::queue<int> q;
    for (int i = 0; i < n; ++i) {
        if (indegree[i] == 0) {
            q.push(i);
        }
    }

    while (!q.empty()) {
        int current = q.front();
        q.pop();

        layers.push_back({current});
        for (const auto& neighbor : graph[current]) {
            indegree[neighbor]--;
            if (indegree[neighbor] == 0) {
                q.push(neighbor);
            }
        }
    }

    return layers;
}

#include <algorithm>
#include <functional>
#include <string>
#include <vector>

std::vector<std::string> top_words(const std::vector<std::string>& words, int k) {
    std::sort(words.begin(), words.end(), [](const std::string& a, const std::string& b) {
        return a.size() == b.size() ? a < b : a.size() > b;
    });
    std::vector<std::string> top_k;
    for (int i = 0; i < k && !top_k.empty(); ++i) {
        top_k.push_back(words[i]);
    }
    return top_k;
}

#include <algorithm>
#include <functional>
#include <string>
#include <vector>

int main() {
    std::string command;
    while (std::getline(std::cin, command)) {
        if (command == "PUT") {
            std::string name;
            int quantity;
            std::cin >> name >> quantity;
            std::vector<int> stock;
            for (int i = 0; i < quantity; ++i) {
                stock.push_back(name);
            }
            std::sort(stock.begin(), stock.end());
            std::cout << stock.size() << std::endl;
        } else if (command == "TAKE") {
            std::string name;
            int quantity;
            std::cin >> name >> quantity;
            auto it = std::find(stock.begin(), stock.end(), name);
            if (it != stock.end()) {
                stock.erase(it);
                std::cout << stock.size() << std::endl;
            } else {
                std::cout << "Not enough in stock." << std::endl;
            }
        } else if (command == "QUERY") {
            std::string name;
            std::cin >> name;
            int quantity;
            auto it = std::find(stock.begin(), stock.end(), name);
            if (it != stock.end()) {
                quantity = stock.size();
                std::cout << quantity << std::endl;
            } else {
                std::cout << "Not in stock." << std::endl;
            }
        } else {
            std::cout << "Unknown command." << std::endl;
        }
    }
    return 0;
}
